492	// writeCloseControl sends a best-effort Close control message to the given
493	// WebSocket connection. Thanks to @pascaldekloe who provided inspiration
494	// from his simple implementation of this I was able to learn from at:
495	// github.com/pascaldekloe/websocket. Further work for handling masking
496	// taken from github.com/gorilla/websocket.
497	func writeCloseControl(conn io.Writer, isClient bool) error {
498		// Sources:
499		// https://github.com/pascaldekloe/websocket/blob/32050af67a5d/websocket.go#L119
500		// https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L413
501	
502		// For now, we're not using a reason. We might later, though.
503		// The code handling the reason is left in
504		var reason string // max 123 bytes (control frame payload limit is 125; status code takes 2)
505	
506		const closeMessage = 8
507		const finalBit = 1 << 7 // Frame header byte 0 bits from Section 5.2 of RFC 6455
508		const maskBit = 1 << 7  // Frame header byte 1 bits from Section 5.2 of RFC 6455
509		const goingAwayUpper uint8 = 1001 >> 8
510		const goingAwayLower uint8 = 1001 & 0xff
511	
512		b0 := byte(closeMessage) | finalBit
513		b1 := byte(len(reason) + 2)
514		if isClient {
515			b1 |= maskBit
516		}
517	
518		buf := make([]byte, 0, 127)
519		buf = append(buf, b0, b1)
520		msgLength := 4 + len(reason)
521	
522		// Both branches below append the "going away" code and reason
523		appendMessage := func(buf []byte) []byte {
524			buf = append(buf, goingAwayUpper, goingAwayLower)
525			buf = append(buf, []byte(reason)...)
526			return buf
527		}
528	
529		// When we're the client, we need to mask the message as per
530		// https://www.rfc-editor.org/rfc/rfc6455#section-5.3
531		if isClient {
532			key := newMaskKey()
533			buf = append(buf, key[:]...)
534			msgLength += len(key)
535			buf = appendMessage(buf)
536			maskBytes(key, 0, buf[2+len(key):])
537		} else {
538			buf = appendMessage(buf)
539		}
540	
541		// simply best-effort, but return error for logging purposes
542		// TODO: we might need to ensure we are the exclusive writer by this point (io.Copy is stopped)?
543		_, err := conn.Write(buf[:msgLength])
544		return err
545	}
546	
547	// Copied from https://github.com/gorilla/websocket/blob/v1.5.0/mask.go
548	func maskBytes(key [4]byte, pos int, b []byte) int {
549		// Mask one byte at a time for small buffers.
550		if len(b) < 2*wordSize {
551			for i := range b {
552				b[i] ^= key[pos&3]
553				pos++
554			}
555			return pos & 3
556		}
557	
558		// Mask one byte at a time to word boundary.
559		if n := int(uintptr(unsafe.Pointer(&b[0]))) % wordSize; n != 0 {
560			n = wordSize - n
561			for i := range b[:n] {
562				b[i] ^= key[pos&3]
563				pos++
564			}
565			b = b[n:]
566		}
567	
568		// Create aligned word size key.
569		var k [wordSize]byte
570		for i := range k {
571			k[i] = key[(pos+i)&3] // nolint:gosec // false positive, impossible to be out of bounds; see: https://github.com/securego/gosec/issues/1525
572		}
573		kw := *(*uintptr)(unsafe.Pointer(&k))
574	
575		// Mask one word at a time.
576		n := (len(b) / wordSize) * wordSize
577		for i := 0; i < n; i += wordSize {
578			*(*uintptr)(unsafe.Add(unsafe.Pointer(&b[0]), i)) ^= kw
579		}
580	
581		// Mask one byte at a time for remaining bytes.
582		b = b[n:]
583		for i := range b {
584			b[i] ^= key[pos&3]
585			pos++
586		}
587	
588		return pos & 3
589	}
590	
591	// Copied from https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L184
592	func newMaskKey() [4]byte {
593		n := weakrand.Uint32()
594		return [4]byte{byte(n), byte(n >> 8), byte(n >> 16), byte(n >> 24)}
595	}
