			}
			fields = make([]zapcore.Field, 0, fieldCount+len(extra.fields))
			fields = append(
				fields,
				zap.Int("bytes_read", reqBodyLength),
				zap.String("user_id", userID),
				zap.Duration("duration", *duration),
				zap.Int("size", size),
