1225	// logRequest logs the request to access logs, unless skipped.
1226	func (s *Server) logRequest(
1227		accLog *zap.Logger, r *http.Request, wrec ResponseRecorder, duration *time.Duration, writeErr *error,
1228		repl *caddy.Replacer, bodyReader *lengthReader, shouldLogCredentials bool,
1229	) {
1230		ctx := r.Context()
1231	
1232		// this request may be flagged as omitted from the logs
1233		if skip, ok := GetVar(ctx, LogSkipVar).(bool); ok && skip {
1234			return
1235		}
1236	
1237		status := wrec.Status()
1238		size := wrec.Size()
1239	
1240		repl.Set("http.response.status", status) // will be 0 if no response is written by us (Go will write 200 to client)
1241		repl.Set("http.response.size", size)
1242		repl.Set("http.response.duration", duration)
1243		repl.Set("http.response.duration_ms", duration.Seconds()*1e3) // multiply seconds to preserve decimal (see #4666)
1244	
1245		loggers := []*zap.Logger{accLog}
1246		if s.Logs != nil {
1247			loggers = s.Logs.wrapLogger(accLog, r)
1248		}
1249	
1250		message := "handled request"
1251		if nop, ok := GetVar(ctx, "unhandled").(bool); ok && nop {
1252			message = "NOP"
1253		}
1254	
1255		logLevel := zapcore.InfoLevel
1256		if status >= 500 {
1257			logLevel = zapcore.ErrorLevel
1258		}
1259	
1260		var fields []zapcore.Field
1261		for _, logger := range loggers {
1262			c := logger.Check(logLevel, message)
1263			if c == nil {
1264				continue
1265			}
1266	
1267			if fields == nil {
1268				userID, _ := repl.GetString("http.auth.user.id")
1269	
1270				reqBodyLength := 0
1271				if bodyReader != nil {
1272					reqBodyLength = bodyReader.Length
1273				}
1274	
1275				extra := ctx.Value(ExtraLogFieldsCtxKey).(*ExtraLogFields)
1276	
1277				hasWriteErr := writeErr != nil && *writeErr != nil
1278	
1279				fieldCount := 6
1280				if hasWriteErr {
1281					fieldCount++
1282				}
1283				fields = make([]zapcore.Field, 0, fieldCount+len(extra.fields))
1284				fields = append(
1285					fields,
1286					zap.Int("bytes_read", reqBodyLength),
1287					zap.String("user_id", userID),
1288					zap.Duration("duration", *duration),
1289					zap.Int("size", size),
1290					zap.Int("status", status),
1291					zap.Object("resp_headers", LoggableHTTPHeader{
1292						Header:               wrec.Header(),
1293						ShouldLogCredentials: shouldLogCredentials,
1294					}),
1295				)
1296				if hasWriteErr {
1297					fields = append(fields, zap.NamedError("write_error", *writeErr))
1298				}
1299				fields = append(fields, extra.fields...)
1300			}
1301	
1302			c.Write(fields...)
1303		}
1304	}
