23	func TestHandlerCopyResponse(t *testing.T) {
24		h := Handler{}
25		testdata := []string{
26			"",
27			strings.Repeat("a", defaultBufferSize),
28			strings.Repeat("123456789 123456789 123456789 12", 3000),
29		}
30	
31		dst := bytes.NewBuffer(nil)
32		recorder := httptest.NewRecorder()
33		recorder.Body = dst
34	
35		for _, d := range testdata {
36			src := bytes.NewBuffer([]byte(d))
37			dst.Reset()
38			err := h.copyResponse(recorder, src, 0, caddy.Log())
39			if err != nil {
40				t.Errorf("failed with error: %v", err)
41			}
42			out := dst.String()
43			if out != d {
44				t.Errorf("bad read: got %q", out)
45			}
46		}
47	}
