129	// A copy error must be reported as-is and must not be mistaken for a clean
130	// half-close, so the tunnel is still torn down immediately.
131	func TestSwitchProtocolCopierErrorIsNotHalfClose(t *testing.T) {
132		var wg sync.WaitGroup
133		errc := make(chan error, 1)
134		wantErr := errors.New("write failed")
135		dst := &closeWriteRecorder{writeErr: wantErr}
136	
137		copier := switchProtocolCopier{
138			user:    nopReadWriteCloser{Reader: strings.NewReader("hello")},
139			backend: dst,
140			wg:      &wg,
141		}
142	
143		wg.Add(1)
144		go copier.copyToBackend(errc)
145		wg.Wait()
146	
147		if err := <-errc; !errors.Is(err, wantErr) {
148			t.Fatalf("error = %v, want %v", err, wantErr)
149		}
150		if dst.called {
151			t.Fatal("CloseWrite() was called after a copy error")
152		}
153	}
