155	func TestSwitchProtocolCopierDefaultBufferSize(t *testing.T) {
156		copier := switchProtocolCopier{}
157		buf := copier.buffer()
158		if got := len(buf); got != defaultBufferSize {
159			t.Fatalf("buffer len = %d, want %d", got, defaultBufferSize)
160		}
