194	// TestHandlerUpgradedStreamHalfClose drives a real upgraded stream through the
195	// handler and checks that closing one direction is propagated to the other side
196	// instead of tearing the whole tunnel down.
197	//
198	// It mirrors net/http/httputil's TestReverseProxyWebSocketHalfTCP, which covers
199	// the same class upstream (https://go.dev/issue/35892). Before the fix, the
200	// "close write" cases failed: the handler returned as soon as the first
201	// direction reported, and the deferred closes killed the other direction before
202	// its pending bytes could be delivered.
203	//
204	// See https://github.com/caddyserver/caddy/issues/8026.
205	func TestHandlerUpgradedStreamHalfClose(t *testing.T) {
206		switch runtime.GOOS {
207		case "plan9", "js", "wasip1":
208			t.Skipf("not supported on %s", runtime.GOOS)
209		}
210	
211		// Reads carry a deadline so a regression fails the test promptly instead of
212		// blocking until the whole package times out.
213		const readTimeout = 10 * time.Second
214	
215		mustRead := func(t *testing.T, conn *net.TCPConn, msg string) {
216			t.Helper()
217			if err := conn.SetReadDeadline(time.Now().Add(readTimeout)); err != nil {
218				t.Fatalf("failed to set read deadline: %v", err)
219			}
220			b := make([]byte, len(msg))
221			if _, err := io.ReadFull(conn, b); err != nil {
222				t.Fatalf("failed to read: %v", err)
223			}
224			if got, want := string(b), msg; got != want {
225				t.Fatalf("got %#q, want %#q", got, want)
226			}
227		}
228	
229		mustReadEOF := func(t *testing.T, conn *net.TCPConn) {
230			t.Helper()
231			if err := conn.SetReadDeadline(time.Now().Add(readTimeout)); err != nil {
232				t.Fatalf("failed to set read deadline: %v", err)
233			}
