	detachedStreams.removeLive([]string{s.upstream})
	detachedStreams.removeLive([]string{s.upstream})
	if err := detachedStreams.closeOrphaned(); err != nil {
		t.Logf("closeOrphaned: %v", err)
	}
	s.waitDone(t)

	after := snapshotStreamMetrics(t, streamResultClosed)
	if after.closed != before.closed+1 {
