// RFC 8441: a WebSocket over an HTTP/2 stream opened with an extended CONNECT.
func TestStreamExtendedConnectOverH2(t *testing.T) {
	t.Setenv("GODEBUG", "http2xconnect=1")
	startUpgradeBackend(t, streamBackendA)
	tester := caddytest.NewTester(t)

	for _, tc := range []struct {
		name string
		opts string
	}{
		{name: "default"},
		{name: "detached", opts: "stream_detached"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			tester.InitServer(fmt.Sprintf(`{
	skip_install_trust
	admin localhost:2999
	http_port     9080
	https_port    9443
	grace_period  1ns
}

localhost:9443 {
	reverse_proxy 127.0.0.1:54331 {
		%s
	}
}`, tc.opts), "caddyfile")

			tr := &http2.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}} //nolint:gosec
			defer tr.CloseIdleConnections()

			pr, pw := io.Pipe()
			req, err := http.NewRequest(http.MethodConnect, "https://localhost:9443/ws", pr)
			if err != nil {
				t.Fatal(err)
			}
			req.Header.Set(":protocol", "websocket")
			req.Header.Set("Sec-WebSocket-Version", "13")

			resp, err := tr.RoundTrip(req)
			if err != nil {
				t.Fatalf("extended CONNECT failed: %v", err)
			}
			defer resp.Body.Close()
			if resp.ProtoMajor != 2 || resp.StatusCode != http.StatusOK {
				t.Fatalf("response is %s %d, want an HTTP/2 200", resp.Proto, resp.StatusCode)
			}

			for _, msg := range []string{"hello over h2", "and again"} {
				if _, err := io.WriteString(pw, msg); err != nil {
					t.Fatalf("writing to the stream: %v", err)
				}
				got := make(chan string, 1)
				go func() {
					buf := make([]byte, len(msg))
					_, _ = io.ReadFull(resp.Body, buf)
					got <- string(buf)
				}()
				select {
				case s := <-got:
					if s != msg {
						t.Fatalf("stream echoed %q, want %q", s, msg)
					}
				case <-time.After(streamWait):
					t.Fatalf("timed out waiting for %q to be echoed", msg)
				}
			}

			// closing our side ends the stream
			pw.Close()
			done := make(chan struct{})
			go func() {
				_, _ = io.Copy(io.Discard, resp.Body)
				close(done)
			}()
			select {
			case <-done:
			case <-time.After(streamWait):
				t.Fatal("the stream did not end after the client closed it")
			}
		})
	}
}

