	}
	if got, _ := closed["bytes_to_backend"].(float64); got < 4 {
		t.Errorf("bytes_to_backend = %v, want at least 4", closed["bytes_to_backend"])
	}
	if got, _ := closed["bytes_from_backend"].(float64); got < 4 {
