package integration

import (
	"testing"

	"github.com/caddyserver/caddy/v2/caddytest"
)

func TestIntercept(t *testing.T) {
	tester := caddytest.NewTester(t)
	tester.InitServer(`{
			skip_install_trust
			admin localhost:2999
			http_port     9080
			https_port    9443
			grace_period  1ns
		}

		localhost:9080 {
			respond /intercept "I'm a teapot" 408
			header /intercept To-Intercept ok
			respond /no-intercept "I'm not a teapot"

			intercept {
				@teapot status 408
				handle_response @teapot {
					header /intercept intercepted {resp.header.To-Intercept}
					respond /intercept "I'm a combined coffee/tea pot that is temporarily out of coffee" 503
				}
			}	
		}
		`, "caddyfile")

	r, _ := tester.AssertGetResponse("http://localhost:9080/intercept", 503, "I'm a combined coffee/tea pot that is temporarily out of coffee")
	if r.Header.Get("intercepted") != "ok" {
		t.Fatalf(`header "intercepted" value is not "ok": %s`, r.Header.Get("intercepted"))
	}

	tester.AssertGetResponse("http://localhost:9080/no-intercept", 200, "I'm not a teapot")
}

// An upgrade is the final response: handle_response routes that match every
// response do not get to intercept it, while regular responses still are.
func TestInterceptUpgradeThroughReverseProxy(t *testing.T) {
	startUpgradeBackend(t, streamBackendA)
	tester := caddytest.NewTester(t)
	tester.InitServer(streamCaddyfile(1, `intercept {
		handle_response {
			respond "intercepted" 200
		}
	}
	reverse_proxy 127.0.0.1:54331`), "caddyfile")

	tester.AssertGetResponse("http://localhost:9080/plain", 200, "intercepted")

	tn := openTunnel(t, "/ws", "echo")
	tn.echo(t, "through intercept")
	tn.echo(t, "and again")

	// the same with a WebSocket handshake
	ws := openTunnel(t, "/ws", "websocket",
		"Sec-WebSocket-Version: 13",
		"Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==")
	ws.echo(t, "websocket through intercept")
}

// The same with the interception done by the reverse proxy's own handle_response.
func TestReverseProxyHandleResponseUpgrade(t *testing.T) {
	startUpgradeBackend(t, streamBackendA)
	tester := caddytest.NewTester(t)
	tester.InitServer(streamCaddyfile(1, `reverse_proxy 127.0.0.1:54331 {
		@upgraded status 101
		handle_response @upgraded {
			copy_response
		}
		stream_detached
	}`), "caddyfile")

	tn := openTunnel(t, "/ws", "echo")
	tn.echo(t, "through handle_response")
	tester.AssertGetResponse("http://localhost:9080/plain", 200, "plain response")
}

func TestInterceptReplaceStatusWithMatcher(t *testing.T) {
	tester := caddytest.NewTester(t)
	tester.InitServer(`{
		skip_install_trust
		admin localhost:2999
		http_port     9080
		https_port    9443
		grace_period  1ns
	}

	localhost:9080 {
		respond /error "boom" 500

		intercept {
			@err status 5xx
			replace_status @err 200
		}
	}
	`, "caddyfile")

	tester.AssertGetResponse("http://localhost:9080/error", 200, "boom")
}

func TestInterceptReplaceStatusWithoutMatcher(t *testing.T) {
	tester := caddytest.NewTester(t)
	tester.InitServer(`{
		skip_install_trust
		admin localhost:2999
		http_port     9080
		https_port    9443
		grace_period  1ns
	}

	localhost:9080 {
		respond /forbidden "denied" 403

		intercept {
			replace_status 200
		}
	}
	`, "caddyfile")

	tester.AssertGetResponse("http://localhost:9080/forbidden", 200, "denied")
}

func TestInterceptReplaceStatusNotMatched(t *testing.T) {
	tester := caddytest.NewTester(t)
	tester.InitServer(`{
		skip_install_trust
		admin localhost:2999
		http_port     9080
		https_port    9443
		grace_period  1ns
	}

	localhost:9080 {
		respond /ok "all good" 200

		intercept {
			@err status 5xx
			replace_status @err 503
		}
	}
	`, "caddyfile")

	// 200 does not match @err (5xx), so status should pass through unchanged
	tester.AssertGetResponse("http://localhost:9080/ok", 200, "all good")
}

