			fields, err := dec.DecodeFull(f.HeaderBlockFragment())
			if err != nil {
				s.events <- h2Event{err: err}
				return
			}
			ev := h2Event{end: f.StreamEnded()}
			for _, field := range fields {
				if field.Name == ":status" {
